import boto3
import unicodedata
import os
from flask import Flask, request, jsonify

app = Flask(__name__)

S3_BUCKET = os.environ.get('S3_BUCKET', 'company-documents-prod')
ALLOWED_PREFIXES = ['public/', 'shared/', 'reports/']

def normalize_path(user_path):
    """Normalize unicode characters in the path for consistent storage."""
    # NFC normalization to handle composed/decomposed unicode variants
    normalized = unicodedata.normalize('NFC', user_path)
    # Replace common unicode lookalikes with ASCII
    normalized = normalized.replace('\u2044', '/')  # fraction slash -> slash
    normalized = normalized.replace('\u2215', '/')  # division slash -> slash
    normalized = normalized.replace('\uff0f', '/')  # fullwidth solidus -> slash
    normalized = normalized.replace('\u2025', '..')  # two dot leader -> ..
    normalized = normalized.replace('\uff0e', '.')   # fullwidth full stop -> .
    return normalized

def check_prefix_allowed(path):
    """Verify the requested path starts with an allowed prefix."""
    for prefix in ALLOWED_PREFIXES:
        if path.startswith(prefix):
            return True
    return False

@app.route('/api/documents/fetch', methods=['POST'])
def fetch_document():
    """Fetch a document from S3 by user-specified path."""
    data = request.get_json()
    if not data or 'path' not in data:
        return jsonify({'error': 'path required'}), 400

    raw_path = data['path']

    # Security check BEFORE normalization
    if not check_prefix_allowed(raw_path):
        return jsonify({'error': 'access denied: invalid prefix'}), 403

    # Reject obvious traversal attempts
    if '..' in raw_path or raw_path.startswith('/'):
        return jsonify({'error': 'invalid path characters'}), 400

    # Normalize AFTER security check - this is the vulnerability
    final_path = normalize_path(raw_path)

    # After normalization, unicode chars may have introduced traversal
    s3_client = boto3.client('s3', region_name='us-east-1')

    try:
        response = s3_client.get_object(Bucket=S3_BUCKET, Key=final_path)
        content = response['Body'].read()
        return jsonify({
            'path': final_path,
            'content': content.decode('utf-8', errors='replace'),
            'size': len(content)
        })
    except s3_client.exceptions.NoSuchKey:
        return jsonify({'error': 'document not found'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/documents/list', methods=['GET'])
def list_documents():
    """List documents under a given prefix."""
    prefix = request.args.get('prefix', 'public/')

    # Same vulnerability pattern for listing
    if not check_prefix_allowed(prefix):
        return jsonify({'error': 'access denied'}), 403

    normalized_prefix = normalize_path(prefix)

    s3_client = boto3.client('s3', region_name='us-east-1')
    try:
        response = s3_client.list_objects_v2(
            Bucket=S3_BUCKET,
            Prefix=normalized_prefix,
            MaxKeys=50
        )
        keys = [obj['Key'] for obj in response.get('Contents', [])]
        return jsonify({'documents': keys})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
